        }

     }
     else if(i+1<(int)s.size()-1 && !flag && i!=0){

        string temp = s.substr(i,2);

        if(temp=="at" && !flag){
          ans+='@';
          i = i+1;
          flag = 1;
          continue;
        }

     }

     ans+=s[i];

  }

  cout<<ans;


  return 0;
}
